//! 🌳️ Original iterative value forests retain scalar edges, all incomplete variants and completed roots.
use super::super::{SemioValue,SemioValueEntry,ValueId,ValueSqliteTables};
use store::sqlite_snapshot::{SqliteDatabase,SqliteSnapshotControl,SqliteSnapshotPhase,SqliteValue,artifact::{RowIndex,RowIndexStorage,reconstruct_text_into,reconstruct_blob_into},transfer::{reserve,heap_sort}};
use semio_framework_value::{ValueError,ValueRefusalKind};
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,message)}
#[derive(semio_framework_value::RetireOwned)]
struct Link{parent:usize,ordinal:i64,child:usize,map_row:Option<usize>}
/// 🧺️ Owns every scalar traversal buffer and partial or completed authored value tree.
#[derive(semio_framework_value::RetireOwned)]
pub struct ValueForestStorage{indexes:[RowIndexStorage;3],links:Vec<Link>,seen:Vec<u8>,complete:Vec<Option<SemioValue>>,restored:Vec<Option<SemioValue>>,pending:Vec<(usize,bool)>}
impl ValueForestStorage{
 pub fn empty()->Self{Self{indexes:std::array::from_fn(|_|RowIndexStorage::empty()),links:Vec::new(),seen:Vec::new(),complete:Vec::new(),restored:Vec::new(),pending:Vec::new()}}
 /// 🫳️ Moves one original completed root without copying its bytes or replacing its backing.
 pub fn take_root(&mut self,index:usize)->Result<SemioValue,ValueError>{self.restored.get_mut(index).and_then(Option::take).ok_or_else(||invalid("missing or multiply consumed Semio value root"))}
 pub fn roots_consumed(&self)->bool{self.restored.iter().all(Option::is_none)}
}
fn locate(rows:&RowIndex<'_>,id:i64,control:&mut SqliteSnapshotControl<'_>)->Result<usize,ValueError>{rows.position(id,control)?.ok_or_else(||invalid("dangling Semio value ownership edge"))}
fn push(pending:&mut Vec<(usize,bool)>,value:(usize,bool))->Result<(),ValueError>{if pending.len()==pending.capacity(){return Err(ValueError::literal(ValueRefusalKind::WorkLimit,"Semio value traversal extent"))}pending.push(value);Ok(())}
/// 🌱️ Builds each real enum variant inside the original caller-owned forest before filling fields or yielding.
pub fn reconstruct_value_forest_into(storage:&mut ValueForestStorage,database:&SqliteDatabase,tables:ValueSqliteTables,roots:&[i64],names:Option<&RowIndex<'_>>,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{
 let phase=SqliteSnapshotPhase::ReconstructSnapshot;let [value_index,list_index,map_index]=&mut storage.indexes;let values=RowIndex::new(value_index,database,tables.value,8,&[],control,"invalid Semio value identity or columns")?;let list=RowIndex::new(list_index,database,tables.list_element,4,&[],control,"invalid Semio list relationship identity")?;let map=RowIndex::new(map_index,database,tables.map_entry,5,&[],control,"invalid Semio map relationship identity")?;let links_count=list.len().checked_add(map.len()).ok_or_else(||invalid("Semio value relationship count overflow"))?;storage.links=reserve(links_count,control)?;
 for(map_member,rows)in [(false,&list),(true,&map)]{for(count,&index)in rows.indices().iter().enumerate(){let row=rows.row(index)?;let parent=locate(&values,row.integer(1)?,control)?;let parent_row=values.row(parent)?;if parent_row.text(1)?!=if map_member{"map"}else{"list"}{return Err(invalid("Semio value relationship has wrong parent kind"))}let child=locate(&values,row.integer(if map_member{4}else{3})?,control)?;if map_member{row.text(3)?;}storage.links.push(Link{parent,ordinal:row.integer(2)?,child,map_row:map_member.then_some(index)});control.checkpoint(phase,count+1,rows.len())?;}}
 heap_sort(&mut storage.links,phase,control,|a,b,_|Ok((a.parent,a.ordinal).cmp(&(b.parent,b.ordinal))))?;let mut parent=None;let mut ordinal=0usize;for(count,link)in storage.links.iter().enumerate(){if parent!=Some(link.parent){parent=Some(link.parent);ordinal=0;}if link.ordinal!=i64::try_from(ordinal).map_err(|_|invalid("Semio value member count overflow"))?{return Err(invalid("Semio value member ordinals must be contiguous"))}ordinal+=1;control.checkpoint(phase,count+1,links_count)?;}
 storage.seen=reserve(values.len(),control)?;storage.complete=reserve(values.len(),control)?;for count in 0..values.len(){storage.seen.push(0);storage.complete.push(None);if count%256==0{control.checkpoint(phase,count,values.len())?;}}storage.restored=reserve(roots.len(),control)?;let extent=links_count.checked_add(roots.len()).and_then(|v|v.checked_add(values.len())).and_then(|v|v.checked_add(1)).ok_or_else(||invalid("Semio value traversal extent overflow"))?;storage.pending=reserve(extent,control)?;let mut count=0usize;
 for &root in roots{let root=locate(&values,root,control)?;push(&mut storage.pending,(root,false))?;while let Some((index,exit))=storage.pending.pop(){count=count.checked_add(1).ok_or_else(||invalid("Semio value reconstruction work overflow"))?;control.checkpoint(phase,count,0)?;let row=values.row(index)?;let from=storage.links.partition_point(|link|link.parent<index);let to=storage.links.partition_point(|link|link.parent<=index);
   if !exit{if storage.seen[index]!=0{return Err(invalid("cyclic or multiply owned Semio value"))}storage.seen[index]=1;push(&mut storage.pending,(index,true))?;for child in storage.links[from..to].iter().rev(){push(&mut storage.pending,(child.child,false))?;}continue}
   let kind=row.text(1)?;let active=match kind{"null"|"list"|"map"=>None,"bool"=>Some(2),"int"=>Some(3),"float"=>Some(4),"str"=>Some(5),"bytes"=>Some(6),"ref"=>Some(7),_=>return Err(invalid("unknown Semio value kind"))};for column in 2..8{if Some(column)!=active&&row.values.get(column)!=Some(&SqliteValue::Null){return Err(invalid("unexpected Semio value variant field"))}}
   storage.complete[index]=Some(match kind{"null"=>SemioValue::Null,"bool"=>SemioValue::Bool{value:match row.integer(2)?{0=>false,1=>true,_=>return Err(invalid("invalid Semio boolean"))}},"int"=>SemioValue::Int{lexeme:String::new()},"float"=>SemioValue::Float{lexeme:String::new()},"str"=>SemioValue::Str{value:String::new()},"bytes"=>SemioValue::Bytes{value:Vec::new()},"ref"=>SemioValue::Ref{id:ValueId{value:String::new()}},"list"=>SemioValue::List{items:Vec::new()},"map"=>SemioValue::Map{entries:Vec::new()},_=>unreachable!()});
   match storage.complete[index].as_mut().unwrap(){SemioValue::Int{lexeme}=>reconstruct_text_into(lexeme,control,row.text(3)?)?,SemioValue::Float{lexeme}=>reconstruct_text_into(lexeme,control,row.text(4)?)?,SemioValue::Str{value}=>reconstruct_text_into(value,control,row.text(5)?)?,SemioValue::Bytes{value}=>reconstruct_blob_into(value,control,row.blob(6)?)?,SemioValue::Ref{id}=>{if let Some(names)=names{let reference=names.get(row.integer(7)?,control)?.ok_or_else(||invalid("dangling Semio value graph reference"))?;reconstruct_text_into(&mut id.value,control,reference.text(3)?)?;}else{reconstruct_text_into(&mut id.value,control,row.text(7)?)?;}},SemioValue::List{items}=>*items=reserve(to-from,control)?,SemioValue::Map{entries}=>*entries=reserve(to-from,control)?,_=>{}}
   for link in &storage.links[from..to]{if kind!="list"&&kind!="map"{return Err(invalid("Semio value primitive has structural children"))}if kind=="map"{let map_row=map.row(link.map_row.ok_or_else(||invalid("missing Semio map key"))?)?;if let SemioValue::Map{entries}=storage.complete[index].as_mut().unwrap(){entries.push(SemioValueEntry{key:String::new(),value:SemioValue::Null});reconstruct_text_into(&mut entries.last_mut().unwrap().key,control,map_row.text(3)?)?;}}let child=storage.complete[link.child].take().ok_or_else(||invalid("missing completed Semio value child"))?;match storage.complete[index].as_mut().unwrap(){SemioValue::List{items}=>items.push(child),SemioValue::Map{entries}=>entries.last_mut().unwrap().value=child,_=>unreachable!()}control.checkpoint(phase,count,0)?;}
  }storage.restored.push(Some(storage.complete[root].take().ok_or_else(||invalid("missing completed Semio root"))?));
 }if storage.seen.iter().any(|seen|*seen==0)||storage.complete.iter().any(Option::is_some){return Err(invalid("unowned Semio value"))}control.checkpoint(phase,count,count)
}
